#include <bits/stdc++.h>
using namespace std;

const int MAX_SIZE=1e6+5;
const int MOD1=998244353;
const int MOD2=1e9+7;
const int BASE_NUM=1000000;

long long total_n;
vector<int> sequence[10];
long long total_count=0;
int prefix_sum[10];
int final_answer=0;

void fill_sequences(int level,int val){
    sequence[level].push_back(((++total_count)-val+MOD1)%MOD1);
    prefix_sum[level]+=sequence[level].back()%MOD2;
    prefix_sum[level]%=MOD2;
    if(level==6) return;
    for(int i=0;i<=9;i++) fill_sequences(level+1,10*val+i);
}

void process(long long x){
    if(x>total_n) return;
    if(x*BASE_NUM+BASE_NUM-1<=total_n && x*BASE_NUM*10>total_n){
        long long rk=total_count;
        for(int i=0,step=1;i<=6;i++,step*=10){
            int delta=((rk - x*step)%MOD1+MOD1)%MOD1;
            int pos=lower_bound(sequence[i].begin(),sequence[i].end(),-delta+MOD1)-sequence[i].begin();
            final_answer+=((1LL*delta*sequence[i].size()%MOD2+prefix_sum[i])%MOD2 - 1LL*(sequence[i].size()-pos)*MOD1%MOD2 +MOD2)%MOD2;
            final_answer%=MOD2;
            total_count+=sequence[i].size();
        }
        return;
    }
    final_answer+=(((++total_count)-x)%MOD1+MOD1)%MOD1;
    final_answer%=MOD2;
    for(int i=0;i<=9;i++) process(x*10+i);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> total_n;
    fill_sequences(0,0);
    for(int i=0;i<=6;i++) sort(sequence[i].begin(),sequence[i].end());
    total_count=0;
    for(int i=1;i<=9;i++) process(i);
    cout << final_answer << "\n";
    return 0;
}
